-- KO-225 group 5: translate Indonesian-only body payloads for English learners (batch 02).
update public.content_variants set body = $json${"text":"Bank Indonesia sets an inflation target of around 2.5% plus or minus 1%. This target is designed so that prices rise slowly enough for people to plan their spending and investments more stably.","source_ids":["e49fe239-c534-4bed-b0bd-a7950b9e35c4","097b62c4-9aae-4933-a870-ac74a526b8f1"]}$json$::jsonb where id = '809a021d-9e46-4018-aa45-4cca7a501080';
update public.content_variants set body = $json${"type":"ordering","answer":["Set specific goals","Set a deadline","Calculate monthly targets","Set aside money at the beginning of the month"],"options":["Set specific goals","Set a deadline","Calculate monthly targets","Set aside money at the beginning of the month"],"question":"Order the steps to set financial goals from start to execution.","difficulty":"beginner","explanation":"Start with specific goals, set a deadline, break it into monthly targets, then set aside money at the beginning."}$json$::jsonb where id = '8277cace-9a5b-44fb-bd28-306b27fe22c1';
update public.content_variants set body = $json${"text":"Rina, a second-semester student in Bandung, receives a monthly allowance of Rp 2,000,000. She notes: boarding Rp 800,000, food Rp 700,000, phone/data Rp 150,000, and savings Rp 200,000. The remaining Rp 150,000 is for entertainment. By keeping track, Rina knows her money is spent on important things, not impulsively.","source_ids":["ad0e8258-4e0a-4378-b257-4fd3628c6953","7f4b83f2-8f1d-415c-9d4f-64e6284bef04"]}$json$::jsonb where id = 'bf53da83-0132-4aa3-823a-02b6675e6f5d';
update public.content_variants set body = $json${"text":"In 2020, a portion of nasi padang at the campus canteen cost Rp 15,000. Three years later, the price became Rp 20,000. The same amount of money now buys a smaller portion. That's inflation eroding purchasing power.","source_ids":["e49fe239-c534-4bed-b0bd-a7950b9e35c4","8da2696d-9836-4a3b-9524-da7e2b823c60"]}$json$::jsonb where id = 'c26876f8-83a6-4c92-bbba-fe3243f10fe0';
update public.content_variants set body = $json${"text":"Andi saw a promotion on Instagram: \"Invest Rp 500,000 to get Rp 5 million in a month, guaranteed safe.\" Andi was suspicious, so he checked the company on the OJK website. It turned out not to be registered. Andi decided not to transfer and reported it to OJK.","source_ids":["9ddb5412-52b8-4461-b2e5-a5443ac63ca8","337c397d-743e-4d1b-8344-09e47b95be90"]}$json$::jsonb where id = 'c649b8b4-7d2d-4f96-bc21-4d322472586b';
update public.content_variants set body = $json${"text":"Lina, a fresh graduate, has Rp 5,000,000 for long-term investment. She decides to spread the funds: 40% into money market mutual funds (low risk), 40% into equity mutual funds (higher risk), and 20% into government bonds. By diversifying, Lina does not rely on a single instrument and reduces the impact if one asset loses value.","source_ids":["47189cc8-8e51-4890-ace4-3f30b913f5ee","07f09c6e-6a98-4fe1-b38f-0868f149ca3e"]}$json$::jsonb where id = 'd6eeab68-bcab-4e5c-a3d7-fbc6a279ecc5';
